def evalRPN(tokens):
    stack = []
    for token in tokens:
        if (len(token) > 1) or token.isdigit():
            # Handles multi-digit and negative numbers
            stack.append(int(token))
        else:
            b = stack.pop()
            a = stack.pop()
            if token == "+":
                stack.append(a + b)
            elif token == "-":
                stack.append(a - b)
            elif token == "*":
                stack.append(a * b)
            elif token == "/":
                # Truncate toward zero, not toward -∞
                stack.append(int(a / b))
    return stack[0]
